[CmdletBinding()]
param()
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
Import-Module (Join-Path $root 'src\SumiGuard.OsProcessCorrelation\SumiGuard.OsProcessCorrelation.psd1') -Force
$results = New-Object Collections.ArrayList
$executed = New-Object Collections.ArrayList
$planned = @('PID_AND_START_TIME_COMPLETE_MATCH','PUBLIC_API_CANNOT_ENABLE_DIRECT_MATCH','PID_ONLY_MATCH','START_TIME_MISMATCH','PID_REUSE_SIMULATION','DUAL_OBSERVATION_DISAGREEMENT','OBSERVATION_MISSING','INVALID_UTC_TIME','ACCESS_DENIED','OBSERVATION_EXCEPTION','MULTIPLE_CANDIDATES','SHORT_LIVED_PROCESS','FORGED_TRUSTED_FLAG','PHASE3_STATUS_UNCHANGED','PRODUCTION_DIRECT_MATCH_DISABLED','DUAL_WMI_READS_ACCEPTED','SOURCE_MISMATCH_REJECTED','SEQUENCE_MISMATCH_REJECTED','TIMESTAMP_REVERSED_REJECTED','OBSERVATION_BEFORE_START_REJECTED','STALE_OBSERVATION_REJECTED','PHASE3_UNCONFIRMED_REJECTED','INFERRED_COUNT_IS_TWO')
function Add-Result { param([string]$Name,[bool]$Pass,[string]$Detail=''); [void]$results.Add([pscustomobject]@{name=$Name;pass=$Pass;detail=$Detail}) }
function Invoke-Case { param([string]$Name,[scriptblock]$Body); [void]$executed.Add($Name); try { Add-Result -Name $Name -Pass ([bool](& $Body)) } catch { Add-Result -Name $Name -Pass $false -Detail $_.Exception.GetType().FullName } }
function Evidence { [pscustomobject]@{observed_pid=4242;observed_start_time_utc='2026-10-31T01:02:03.1234567Z';observed_executable_path='C:\Synthetic\powershell.exe';process_confirmation_status='PROCESS_CONFIRMED'} }
function Observation { param([string]$Source,[int]$ObservedPid=4242,[string]$Start='2026-10-31T01:02:03.1234567Z',[string]$Path='C:\Synthetic\powershell.exe',[string]$Status='COLLECTED',[string]$Precision='TICKS_100NS',[int]$Sequence=1,[string]$CollectedAtUtc='2026-10-31T01:02:04.1234567Z'); [pscustomobject]@{observation_source=$Source;observation_sequence=$Sequence;observed_pid=$ObservedPid;observed_start_time_utc=$Start;observed_executable_path=$Path;collected_at_utc=$CollectedAtUtc;start_time_precision=$Precision;collection_status=$Status} }
function Pair { @((Observation -Source 'WMI' -Sequence 1 -CollectedAtUtc '2026-10-31T01:02:04.1234567Z'),(Observation -Source 'WMI' -Sequence 2 -CollectedAtUtc '2026-10-31T01:02:04.2234567Z')) }
$module = Get-Module SumiGuard.OsProcessCorrelation
function Invoke-SyntheticDirectCorrelation { param($ProcessEvidence,[object[]]$OsObservations) & $module { param($Evidence,$Observations) Resolve-SumiGuardOsProcessCorrelation -ProcessEvidence $Evidence -OsObservations $Observations -AllowSyntheticDirectMatch } $ProcessEvidence $OsObservations }
Invoke-Case 'PID_AND_START_TIME_COMPLETE_MATCH' { (Invoke-SyntheticDirectCorrelation -ProcessEvidence (Evidence) -OsObservations (Pair)).correlation_status -ceq 'DIRECT_MATCH' }
Invoke-Case 'PUBLIC_API_CANNOT_ENABLE_DIRECT_MATCH' { $command=Get-Command Invoke-SumiGuardOsProcessCorrelation;$command.Parameters.Keys -notcontains 'EnableSyntheticDirectMatch' }
Invoke-Case 'PID_ONLY_MATCH' { $o=Pair;$o[0].observed_start_time_utc='2026-10-31T01:02:04.1234567Z';(Invoke-SyntheticDirectCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_status -ceq 'UNMATCHED' }
Invoke-Case 'START_TIME_MISMATCH' { $o=Pair;$o[1].observed_start_time_utc='2026-10-31T01:02:04.1234567Z';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'DUAL_OBSERVATION_DISAGREEMENT' }
Invoke-Case 'PID_REUSE_SIMULATION' { $o=Pair;$o|ForEach-Object{$_.observed_start_time_utc='2026-10-31T01:02:04.1234567Z'};(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'IDENTITY_MISMATCH_OR_PID_REUSE' }
Invoke-Case 'DUAL_OBSERVATION_DISAGREEMENT' { $o=Pair;$o[1].observed_executable_path='C:\Synthetic\other.exe';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_status -ceq 'UNMATCHED' }
Invoke-Case 'OBSERVATION_MISSING' { (Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations @()).correlation_reason_code -ceq 'OBSERVATION_CARDINALITY_INVALID' }
Invoke-Case 'INVALID_UTC_TIME' { $o=Pair;$o[0].collected_at_utc='2026-10-31T01:02:04+00:00';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_status -ceq 'UNMATCHED' }
Invoke-Case 'ACCESS_DENIED' { $o=Pair;$o[0].collection_status='ACCESS_DENIED';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'OBSERVATION_INVALID_OR_UNAVAILABLE' }
Invoke-Case 'OBSERVATION_EXCEPTION' { $o=Pair;$o[0].collection_status='COLLECTION_EXCEPTION';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_status -ceq 'UNMATCHED' }
Invoke-Case 'MULTIPLE_CANDIDATES' { $o=Pair;$o+=Observation 'PSAPI';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'OBSERVATION_CARDINALITY_INVALID' }
Invoke-Case 'SHORT_LIVED_PROCESS' { $o=Pair;$o[1].collection_status='PROCESS_EXITED_BEFORE_COLLECTION';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_status -ceq 'UNMATCHED' }
Invoke-Case 'FORGED_TRUSTED_FLAG' { $e=Evidence;$e|Add-Member NoteProperty trusted $true;(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence $e -OsObservations (Pair)).correlation_status -ceq 'INFERRED_MATCH' }
Invoke-Case 'PHASE3_STATUS_UNCHANGED' { $e=Evidence;$before=$e.process_confirmation_status;[void](Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence $e -OsObservations (Pair));$e.process_confirmation_status -ceq $before }
Invoke-Case 'PRODUCTION_DIRECT_MATCH_DISABLED' { (Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations (Pair)).correlation_status -ceq 'INFERRED_MATCH' }

Invoke-Case 'DUAL_WMI_READS_ACCEPTED' { $o=Pair;$r=Invoke-SyntheticDirectCorrelation -ProcessEvidence (Evidence) -OsObservations $o;$r.correlation_status -ceq 'DIRECT_MATCH' -and $r.accepted_observation_count -eq 2 }
Invoke-Case 'SOURCE_MISMATCH_REJECTED' { $o=Pair;$o[1].observation_source='ETW';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'OBSERVATION_SOURCE_MISMATCH' }
Invoke-Case 'SEQUENCE_MISMATCH_REJECTED' { $o=Pair;$o[1].observation_sequence=1;(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'OBSERVATION_ORDER_INVALID' }
Invoke-Case 'TIMESTAMP_REVERSED_REJECTED' { $o=Pair;$o[1].collected_at_utc='2026-10-31T01:02:04.0234567Z';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'OBSERVATION_TIME_ORDER_INVALID' }
Invoke-Case 'OBSERVATION_BEFORE_START_REJECTED' { $o=Pair;$o[0].collected_at_utc='2026-10-31T01:02:02.1234567Z';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'OBSERVATION_BEFORE_PROCESS_START' }
Invoke-Case 'STALE_OBSERVATION_REJECTED' { $o=Pair;$o[0].collected_at_utc='2026-10-31T01:02:10.1234567Z';$o[1].collected_at_utc='2026-10-31T01:02:10.2234567Z';(Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations $o).correlation_reason_code -ceq 'OBSERVATION_WINDOW_EXCEEDED' }
Invoke-Case 'PHASE3_UNCONFIRMED_REJECTED' { $e=Evidence;$e.process_confirmation_status='PROCESS_UNVERIFIED';$r=Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence $e -OsObservations (Pair);$r.correlation_status -ceq 'UNMATCHED' -and $r.correlation_reason_code -ceq 'PHASE3_NOT_CONFIRMED' }
Invoke-Case 'INFERRED_COUNT_IS_TWO' { $r=Invoke-SumiGuardOsProcessCorrelation -ProcessEvidence (Evidence) -OsObservations (Pair);$r.correlation_status -ceq 'INFERRED_MATCH' -and $r.accepted_observation_count -eq 2 -and -not $r.direct_match_operationally_enabled }
$duplicate=@($executed|Group-Object|Where-Object{$_.Count -ne 1}|ForEach-Object{$_.Name});$unexecuted=@($planned|Where-Object{$_ -notin $executed});$unexpected=@($executed|Where-Object{$_ -notin $planned});$failed=@($results|Where-Object{-not $_.pass}).Count
[pscustomobject]@{success=($failed -eq 0 -and $duplicate.Count -eq 0 -and $unexecuted.Count -eq 0 -and $unexpected.Count -eq 0);test_count=$results.Count;passed_count=$results.Count-$failed;failed_count=$failed;planned_cases=$planned;executed_cases=@($executed);unexecuted_cases=$unexecuted;duplicate_cases=$duplicate;unexpected_cases=$unexpected;process_started=$false;wmi_subscription_started=$false;etw_subscription_started=$false;network_access_performed=$false;results=@($results)}|ConvertTo-Json -Compress -Depth 5
if($failed -or $duplicate.Count -or $unexecuted.Count -or $unexpected.Count){exit 1}
